import pandas as pd
from random import randint, seed

def task_func(dictionary, item, sample_size=None, random_seed=None):
    df = pd.DataFrame(dictionary)

    # Find all exact matches of `item`
    search_is_nan = item != item
    positions = []
    for row in df.index:
        for col in df.columns:
            value = df.at[row, col]
            if search_is_nan:
                if value != value:
                    positions.append((row, col))
            elif value == item:
                positions.append((row, col))

    # Optional random sampling of positions
    if sample_size is not None:
        if random_seed is not None:
            seed(random_seed)

        if sample_size <= 0:
            positions = []
        elif sample_size < len(positions):
            pool = positions.copy()
            sampled = []
            for _ in range(sample_size):
                idx = randint(0, len(pool) - 1)
                sampled.append(pool.pop(idx))
            positions = sampled

    return positions, df
